// Package cli owns command-line parsing, dispatch, diagnostics, and exit codes.
package cli

import (
	"flag"
	"fmt"
	"io"
)

const (
	// ExitOK indicates a successful command.
	ExitOK = 0
	// ExitOperational indicates an operational failure.
	ExitOperational = 1
	// ExitUsage indicates invalid command-line usage.
	ExitUsage = 2
	// ExitRejected indicates input rejected by the profiler.
	ExitRejected = 3
)

// Run parses args, dispatches the requested command, and returns its process exit code.
func Run(args []string, stdout, stderr io.Writer) int {
	flags := flag.NewFlagSet("csvstat", flag.ContinueOnError)
	flags.SetOutput(stderr)
	help := flags.Bool("help", false, "show command usage")
	if err := flags.Parse(args); err != nil {
		return ExitUsage
	}
	if *help {
		if _, err := fmt.Fprintln(stdout, "usage: csvstat [flags] file.csv"); err != nil {
			return ExitOperational
		}
		flags.PrintDefaults()
		return ExitOK
	}
	if flags.NArg() != 1 {
		_, _ = fmt.Fprintln(stderr, "usage: csvstat [flags] file.csv")
		return ExitUsage
	}

	// Profiling dispatch is intentionally kept behind this boundary. The CSV domain
	// package owns loading and analysis; this package owns process-facing concerns.
	_, _ = fmt.Fprintln(stderr, "csvstat: profiling command not configured")
	return ExitOperational
}
// Package csvstat owns CSV loading, normalization, profiling, frequency aggregation,
// and rendering. It does not read command-line arguments or terminate the process.
package csvstat

import (
	"encoding/csv"
	"fmt"
	"io"
)

// Record is one normalized CSV record.
type Record []string

// Input is the domain representation passed from loading into profiling.
type Input struct {
	Header  Record
	Records []Record
}

// Load reads one RFC 4180 CSV stream and returns its records. It does not access
// the filesystem, so callers control the source and tests can use any io.Reader.
func Load(reader io.Reader) (Input, error) {
	rows, err := csv.NewReader(reader).ReadAll()
	if err != nil {
		return Input{}, fmt.Errorf("read csv: %w", err)
	}
	if len(rows) == 0 {
		return Input{}, fmt.Errorf("read csv: empty input")
	}
	input := Input{Header: Record(rows[0])}
	for _, row := range rows[1:] {
		input.Records = append(input.Records, Record(row))
	}
	return input, nil
}
package cli

import (
	"bytes"
	"testing"
)

func TestRunRejectsMissingInput(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run(nil, &stdout, &stderr)

	if code != ExitUsage {
		t.Fatalf("Run(nil) = %d, want %d", code, ExitUsage)
	}
	if stdout.Len() != 0 {
		t.Fatalf("stdout length = %d, want 0", stdout.Len())
	}
}

func TestRunPrintsHelp(t *testing.T) {
	var stdout, stderr bytes.Buffer

	code := Run([]string{"-help"}, &stdout, &stderr)

	if code != ExitOK {
		t.Fatalf("Run(-help) = %d, want %d", code, ExitOK)
	}
	if stdout.Len() == 0 {
		t.Fatal("help output is empty")
	}
}
package csvstat

import (
	"strings"
	"testing"
)

func TestLoadSeparatesHeaderAndRecords(t *testing.T) {
	input, err := Load(strings.NewReader("name,age\nAda,36\n"))
	if err != nil {
		t.Fatalf("Load returned error: %v", err)
	}
	if len(input.Header) != 2 || input.Header[0] != "name" || input.Header[1] != "age" {
		t.Fatalf("header = %#v, want [name age]", input.Header)
	}
	if len(input.Records) != 1 || input.Records[0][0] != "Ada" {
		t.Fatalf("records = %#v, want one Ada record", input.Records)
	}
}

func TestLoadRejectsEmptyInput(t *testing.T) {
	_, err := Load(strings.NewReader(""))
	if err == nil {
		t.Fatal("Load(empty) returned nil error")
	}
}
